static struct Node *cloneNode(struct Node *node, struct Node **visited) {
  if (node == NULL) {
    return NULL;
  }
  if (visited[node->val] != NULL) {
    return visited[node->val];
  }
  struct Node *copy = (struct Node *)malloc(sizeof(struct Node));
  copy->val = node->val;
  copy->numNeighbors = 0;
  visited[node->val] = copy;
  for (int i = 0; i < node->numNeighbors; i++) {
    copy->neighbors[copy->numNeighbors++] = cloneNode(node->neighbors[i], visited);
  }
  return copy;
}

struct Node *cloneGraph(struct Node *node) {
  struct Node *visited[101] = {NULL};
  return cloneNode(node, visited);
}

class Solution {
public:
  unordered_map<Node *, Node *> visited;

  Node *cloneGraph(Node *node) {
    if (node == nullptr) {
      return nullptr;
    }
    if (visited.count(node)) {
      return visited[node];
    }
    Node *copy = new Node(node->val);
    visited[node] = copy;
    for (Node *neighbor : node->neighbors) {
      copy->neighbors.push_back(cloneGraph(neighbor));
    }
    return copy;
  }
};

func cloneGraph(node *Node) *Node {
	if node == nil {
		return nil
	}
	visited := map[*Node]*Node{}

	var dfs func(*Node) *Node
	dfs = func(n *Node) *Node {
		if n == nil {
			return nil
		}
		if copy, ok := visited[n]; ok {
			return copy
		}
		copy := &Node{Val: n.Val}
		visited[n] = copy
		for _, neighbor := range n.Neighbors {
			copy.Neighbors = append(copy.Neighbors, dfs(neighbor))
		}
		return copy
	}

	return dfs(node)
}

class Node {
  public int val;
  public List<Node> neighbors;

  public Node() {
    val = 0;
    neighbors = new ArrayList<Node>();
  }

  public Node(int _val) {
    val = _val;
    neighbors = new ArrayList<Node>();
  }
}

class Solution {
  private Map<Node, Node> visited = new HashMap<Node, Node>();

  public Node cloneGraph(Node node) {
    if (node == null) {
      return null;
    }
    if (visited.containsKey(node)) {
      return visited.get(node);
    }
    Node clone = new Node(node.val);
    visited.put(node, clone);
    for (Node neighbor : node.neighbors) {
      clone.neighbors.add(cloneGraph(neighbor));
    }
    return clone;
  }
}

class Solution:
    def cloneGraph(self, node: Optional["Node"]) -> Optional["Node"]:
        if node is None:
            return None

        visited = {}

        def dfs(current: "Node") -> "Node":
            if current in visited:
                return visited[current]
            copy = Node(current.val)
            visited[current] = copy
            for neighbor in current.neighbors:
                copy.neighbors.append(dfs(neighbor))
            return copy

        return dfs(node)

impl Solution {
  pub fn clone_graph(node: Option<Rc<RefCell<Node>>>) -> Option<Rc<RefCell<Node>>> {
    fn dfs(n: &Rc<RefCell<Node>>, visited: &mut HashMap<usize, Rc<RefCell<Node>>>) -> Rc<RefCell<Node>> {
      let key = Rc::as_ptr(n) as usize;
      if let Some(copy) = visited.get(&key) {
        return copy.clone();
      }
      let copy = Rc::new(RefCell::new(Node::new(n.borrow().val)));
      visited.insert(key, copy.clone());
      let neighbors = n.borrow().neighbors.clone();
      for neighbor in neighbors {
        let cloned = dfs(&neighbor, visited);
        copy.borrow_mut().neighbors.push(cloned);
      }
      copy
    }

    node.map(|n| dfs(&n, &mut HashMap::new()))
  }
}

const cloneGraph = (node: Node | null): Node | null => {
  if (node === null) return null;

  const visited = new Map<Node, Node>();

  const dfs = (current: Node): Node => {
    const cached = visited.get(current);
    if (cached) return cached;
    const copy = new Node(current.val);
    visited.set(current, copy);
    for (const neighbor of current.neighbors) {
      copy.neighbors.push(dfs(neighbor));
    }
    return copy;
  };

  return dfs(node);
};
